import re

def solve(data):
    pattern = data['pattern']
    text = data['text']

    # Use regular expression to match the pattern with the text
    if pattern == "*":
        return True
    elif pattern == "?":
        return len(text) > 0
    else:
        try:
            return bool(re.match(f"^{re.escape(pattern)}$", text))
        except re.error:
            return False
